const POLARIS_PROJECT_OVERVIEWS={
 "TapBin":"PRODUCT OVERVIEW FROM THE TAPBIN SOURCE README: TapBin is North Star Ventures' multi-tenant inventory, storage and resale management system (tapbin.ca), initially built for Great Church and expanded for churches, businesses and personal inventory. It organises items into areas/rooms, bins and nested storage; supports search, adding or relocating items, NFC label/tap access, protected viewer PINs, organization administrators and moderators, invite-only onboarding, AI-assisted inventory entry, inventory reconciliation/re-inventory, and optional store/resale workflows. The primary GitHub codebase is northstarventuresca-livebridge/northstar-organizer, even though that repository name does not include TapBin. Features and security permissions are documented in its README; current production state needs fresh verification. When someone asks what TapBin is or how it works, describe this product directly rather than saying you only have its name.",
 "X32 AI Engineer":"PROJECT OVERVIEW FROM VERIFIED DISCUSSIONS: A Behringer X32 mixer companion intended to analyze individual vocal microphones via Dante audio and offer/apply voice-specific EQ suggestions. Goals include recognizing singers or speakers by voiceprint, loading saved starting EQ per person, monitoring live voice, and checking mixer EQ through X32 OSC. Known deployed church Worker name: x32-ai-engineer-church, in the separate Global Connections Church Cloudflare account. A separate authorized church Cloudflare source connection is needed to inspect its live Worker, and status of the current mixer connection cannot be inferred from the project name.",
 "HOH HUB":"PROJECT OVERVIEW: Home of Hope sponsorship administration and public sponsorship platform; child and microloan sponsorships, directory controls, staff/volunteers, sponsors and financial records, reports, marketing and approvals. Details and status are subject to source verification.",
 "LiveBridge":"PROJECT OVERVIEW: North Star Ventures live voice translation, transcription and listener/broadcaster communications platform, with organizations, campuses and separate admin controls. Review actual LiveBridge repo and Worker state for implementation details.",
 "Songwriters Compass":"PROJECT OVERVIEW: North Star Ventures AI-assisted songwriting workspace with theological guardrails for songwriters; source and active feature details require verification."
};

const POLARIS_KNOWN_PROJECTS=[
 "North Star Ventures","HOH HUB","LiveBridge","TapBin","Songwriters Compass",
 "X32 AI Engineer","Great Church","Healing The Heart","Northstar Organizer",
 "Polaris","Other / Client Projects"
];
function polarisProjectName(text){
 const t=String(text||"").toLowerCase().replace(/^(?:hey|hi)\s+polaris[,\s]*/,"");
 if(/\b(?:hoh|home of hope|microloans?|sponsorships?)\b/.test(t))return "HOH HUB";
 if(t.includes("livebridge")||t.includes("live bridge"))return "LiveBridge";
 if(/\btap\s*(?:bin|been|bean|bend)\b/i.test(t)||t.includes("tapbin"))return "TapBin";
 if(t.includes("songwriters")||t.includes("songwriter")||t.includes("compass"))return "Songwriters Compass";
 if(/\bx32\b/.test(t)||t.includes("audio engineer"))return "X32 AI Engineer";
 if(t.includes("great church")||t.includes("greatchurch"))return "Great Church";
 if(t.includes("healing the heart")||t.includes("hth"))return "Healing The Heart";
 if(t.includes("northstar organizer")||t.includes("northstar-organizer"))return "Northstar Organizer";
 if(/\bpolaris\b/.test(t)&&/\b(?:app|project|dashboard|worker|code|files?|settings|website|hub)\b/.test(t))return "Polaris";
 if(t.includes("north star ventures")||t.includes("northstar ventures"))return "North Star Ventures";
 return "";
}
async function polarisProjectContext(env,project,query){
 if(!env.POLARIS_DB)return {name:"",notes:"Project registry unavailable"};
 const text=String(query||"");
 const named=polarisProjectName(text);
 const chosen=named||(POLARIS_KNOWN_PROJECTS.includes(project)?project:"");
 const listAll=/\b(?:all|every|list|which|what|show)\b.*\b(?:projects|repositories|repos|workers)\b|\b(?:my projects|project list)\b/i.test(text);
 try{
  if(!chosen&&listAll){
   const rows=await env.POLARIS_DB.prepare("SELECT project,source,count(*) AS count FROM project_registry GROUP BY project,source ORDER BY project,source LIMIT 50").all();
   const desc=(rows.results||[]).map(r=>r.project+" · "+r.source+": "+r.count).join("\n");
   return {name:"All tracked resources",notes:"Verified metadata snapshot (not live inventory); repo file contents are not indexed in full.\n"+desc.slice(0,6000)};
  }
  if(!chosen)return {name:"",notes:""};
  const detailed=/\b(?:how|why|code|source|readme|file|repository|repo|detail|architecture|implementation|features|changes|built|build|develop|docs|inspect|review|what did|last)\b/i.test(text);
  const maxDocSections=detailed?8:1;
  const [found,documents]=await Promise.all([
   env.POLARIS_DB.prepare("SELECT source,name,path,visibility,notes FROM project_registry WHERE project=? ORDER BY source,name LIMIT 45").bind(chosen).all(),
   env.POLARIS_DB.prepare("SELECT repository,path,chunk_number,body,captured_at FROM project_documents WHERE project=? ORDER BY repository,path,chunk_number LIMIT ?").bind(chosen,maxDocSections).all()
  ]);
  const resources=(found.results||[]).map(r=>r.source+": "+r.name+(r.visibility?" ["+r.visibility+"]":"")).join("\n");
  const refs=(documents.results||[]).map(r=>"[README snapshot "+r.repository+"/"+r.path+", section "+r.chunk_number+"]\n"+String(r.body).slice(0,1550)).join("\n\n");
  const notes="VERIFIED PROJECT OVERVIEW:\n"+(POLARIS_PROJECT_OVERVIEWS[chosen]||"Project identity is recognized; consult source excerpts for verified details.")+"\n\nPROJECT SOURCE INVENTORY (read-only snapshot, not live sync):\n"+resources.slice(0,detailed?5900:1700)+
   "\n\nPROJECT DOCUMENT EXCERPTS (limited README snapshots, not entire codebase):\n"+refs.slice(0,detailed?8000:900)+
   "\n\nIMPORTANT: Do not claim files have been read live or that these are current deployments. For deeper or current analysis of private GitHub code and Cloudflare source, a separately authorized scoped read-only connection must be added.";
  return {name:chosen,notes};
 }catch(e){return {name:chosen,notes:"Project registry could not be loaded at this time."}}
}
async function polarisProjectIndex(env){
 if(!env.POLARIS_DB)return {projects:[],error:"Project database unavailable"};
 try{
  const counts=await env.POLARIS_DB.prepare("SELECT project,source,count(*) AS count FROM project_registry GROUP BY project,source ORDER BY project,source").all();
  const docs=await env.POLARIS_DB.prepare("SELECT project,count(DISTINCT repository) AS repositories, count(*) AS sections FROM project_documents GROUP BY project").all();
  const groups=Object.create(null);
  for(const r of counts.results||[]){
   if(!groups[r.project])groups[r.project]={name:r.project,github:0,workers:0,documents:0};
   if(r.source==="github")groups[r.project].github+=r.count||0;
   else if(r.source==="cloudflare-worker")groups[r.project].workers+=r.count||0;
  }
  for(const r of docs.results||[])if(groups[r.project])groups[r.project].documents=r.sections||0;
  return {projects:Object.values(groups),source:"verified account snapshots",live_repo_content:Boolean(env.POLARIS_GITHUB_NSV_READ_TOKEN||env.POLARIS_GITHUB_CHURCH_READ_TOKEN||env.POLARIS_GITHUB_PERSONAL_READ_TOKEN),live_cloudflare_access:Boolean(env.POLARIS_CF_NSV_READ_TOKEN)};
 }catch(e){return {projects:[],error:"Unable to load project registry"}}
}

// Polaris live source reader v2.1 — authenticated, read-only, least privilege.
// Only examines registered resources and fetches small relevant text portions.
// Optional secrets (not configured until owner adds them):
// POLARIS_GITHUB_NSV_READ_TOKEN, POLARIS_GITHUB_CHURCH_READ_TOKEN,
// POLARIS_GITHUB_PERSONAL_READ_TOKEN, POLARIS_CF_NSV_READ_TOKEN.
const POLARIS_CF_NSV_ACCOUNT="de139270326790931c82df02d785528f";
function polarisSourceTokens(env){
 return {
  githubNSV:Boolean(env.POLARIS_GITHUB_NSV_READ_TOKEN),
  githubChurch:Boolean(env.POLARIS_GITHUB_CHURCH_READ_TOKEN),
  githubPersonal:Boolean(env.POLARIS_GITHUB_PERSONAL_READ_TOKEN),
  cloudflareNSV:Boolean(env.POLARIS_CF_NSV_READ_TOKEN)
 };
}
function polarisSourceSafe(path){
 const p=String(path||"").toLowerCase();
 if(!p||p.length>300||p.includes("..")||p.startsWith("/")||p.includes("\\"))return false;
 if(/(^|\/)(?:\.env(?:\..*)?|\.git|node_modules|vendor|secrets?|credentials?|private|certs?|\.wrangler|dist|build)(\/|$)/i.test(p))return false;
 if(/\.(?:pem|p12|pfx|key|keystore|crt|cer|sqlite|db|wasm|zip|lock|min\.js|map|png|jpg|jpeg|gif|webp|svg|mp3|mp4|pdf|woff2?)$/i.test(p))return false;
 if(/(?:token|password|secret|credentials|privatekey|private_key)/i.test(p.split("/").pop()))return false;
 return /\.(?:md|txt|js|mjs|cjs|ts|tsx|jsx|html|css|json|toml|yaml|yml|py|go|rs|sh)$/i.test(p);
}
function polarisRedactSource(content){
 return String(content||"").slice(0,12500)
  .replace(/-----BEGIN [^-]*PRIVATE KEY-----[\s\S]*?-----END [^-]*PRIVATE KEY-----/g,"[REDACTED PRIVATE KEY]")
  .replace(/\b(?:sk-[A-Za-z0-9_-]{16,}|gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|AKIA[A-Z0-9]{16})\b/g,"[REDACTED CREDENTIAL]")
  .replace(/(\b(?:token|password|secret|api[_ -]?key|private[_ -]?key)\b\s*[:=]\s*["']?)[A-Za-z0-9_./+!=-]{12,}/gi,"$1[REDACTED]")
  .slice(0,11000);
}
function polarisRepoToken(env,repo){
 const owner=repo.split("/")[0];
 if(owner==="northstarventuresca-livebridge")return env.POLARIS_GITHUB_NSV_READ_TOKEN;
 if(owner==="globalconnectionschurch-eng")return env.POLARIS_GITHUB_CHURCH_READ_TOKEN;
 if(owner==="rwyers")return env.POLARIS_GITHUB_PERSONAL_READ_TOKEN;
 return null;
}
function polarisSourceInterest(query){
 return /\b(?:read|inspect|look at|show|check|search|find|source|repo|repository|github|code|files?|scripts?|workers?|cloudflare|configuration|latest|currently|recent|what changed|implementation|deployed|deployment|live status)\b/i.test(query);
}
async function polarisLiveSources(env,selectedProject,query){
 if(!env.POLARIS_DB||!polarisSourceInterest(query))return "";
 const project=selectedProject||polarisProjectName(query);
 if(!project||project==="All tracked resources")return "";
 const lower=String(query||"").toLowerCase(),parts=[];
 const sourceRows=await env.POLARIS_DB.prepare("SELECT source,name,path,visibility,notes FROM project_registry WHERE project=? ORDER BY name LIMIT 50").bind(project).all();
 const all=sourceRows.results||[];
 const qTerms=lower.split(/[^a-z0-9]+/).filter(v=>v.length>=3&&!["the","and","from","with","that","this","have","about","what","could","would","tell","please","last","latest","your","project"].includes(v));
 const gh=all.filter(r=>r.source==="github");
 const cf=all.filter(r=>r.source==="cloudflare-worker");
 // Look up at most one GitHub repository and up to two relevant files.
 if(/\b(?:github|repository|repo|code|file|source|readme|implementation|scripts?)\b/i.test(query)){
  let candidates=gh.filter(r=>r.visibility==="public"||polarisRepoToken(env,r.path));
  if(!candidates.length){
   parts.push("Live private GitHub file reading is not connected for this project. A repository-scoped GitHub Contents Read token is required.");
  }else{
   candidates.sort((a,b)=>{
    const score=r=>{
     const name=r.name.toLowerCase(),repoPart=name.split("/").pop();
     let s=qTerms.filter(x=>name.includes(x)).length*7;
     if(lower.includes(repoPart))s+=10;
     if(project==="LiveBridge"&&name.includes("production"))s+=5;
     if(project==="TapBin"&&name.includes("organizer"))s+=5;
     if(name.includes("allinone"))s+=1;
     return s;
    };
    return score(b)-score(a);
   });
   const chosen=candidates[0],repo=chosen.path,token=polarisRepoToken(env,repo);
   const [owner,repoName]=repo.split("/");
   const headers={"user-agent":"Polaris-ReadOnly/2.1","accept":"application/vnd.github+json","x-github-api-version":"2026-03-10"};
   if(token)headers.authorization="Bearer "+token;
   try{
    const treeResponse=await fetch("https://api.github.com/repos/"+encodeURIComponent(owner)+"/"+encodeURIComponent(repoName)+"/git/trees/main?recursive=1",{headers});
    if(treeResponse.ok){
     const tree=await treeResponse.json();
     const files=(tree.tree||[]).filter(x=>x.type==="blob"&&polarisSourceSafe(x.path)&&x.size<=45000);
     const rank=f=>{
      const p=f.path.toLowerCase();let s=qTerms.filter(term=>p.includes(term)).length*7;
      if(project==="HOH HUB"&&/(hoh|hope|sponsor)/.test(p))s+=8;
      if(project==="LiveBridge"&&p.includes("livebridge"))s+=5;
      if(p.endsWith("readme.md"))s+=2;
      if(/\/(?:tests?|fixtures?|archives?|legacy|backup)\//.test(p))s-=8;
      if(/\/(?:api|src|worker|server)\//.test(p))s+=1;
      return s;
     };
     files.sort((a,b)=>rank(b)-rank(a));
     const chosenFiles=files.slice(0,2).filter(f=>rank(f)>0||files.length===1);
     for(const file of chosenFiles){
      try{
       const u="https://api.github.com/repos/"+encodeURIComponent(owner)+"/"+encodeURIComponent(repoName)+"/contents/"+file.path.split("/").map(encodeURIComponent).join("/");
       const r=await fetch(u,{headers:{...headers,accept:"application/vnd.github.raw+json"}});
       if(!r.ok)continue;
       let body=await r.text();
       if(body.startsWith('{"type":"file"')){
        try{const o=JSON.parse(body);if(o.encoding==="base64"&&typeof o.content==="string")body=atob(o.content.replace(/\s+/g,""))}catch(e){}
       }
       parts.push("[LIVE GITHUB READ — "+repo+"/"+file.path+"]\n"+polarisRedactSource(body).slice(0,4200));
      }catch(e){}
     }
     if(!chosenFiles.length)parts.push("GitHub read succeeded for "+repo+", but no small relevant text files matched. Ask for a specific filename or directory.");
    }else parts.push("GitHub "+repo+" live read returned HTTP "+treeResponse.status+". Access to private files may need a correct read-only token.");
   }catch(e){parts.push("GitHub source read was temporarily unavailable.")}
  }
 }
 // Read Cloudflare Worker source only for an explicit Worker/Cloudflare question.
 if(/\b(?:cloudflare|worker|script|workers)\b/i.test(query)){
  if(!env.POLARIS_CF_NSV_READ_TOKEN){
   parts.push("Cloudflare Worker source has not been connected live; the known Worker names are inventory snapshots only. A Workers Scripts Read token is required.");
  }else{
   const named=cf.filter(r=>lower.includes(r.name.toLowerCase()));
   const worker=named.length===1?named[0]:(cf.length===1?cf[0]:null);
   if(!worker){
    parts.push("There are "+cf.length+" registered Cloudflare Worker names for "+project+". Specify the particular script name to inspect its live source.");
   }else{
    try{
     const url="https://api.cloudflare.com/client/v4/accounts/"+POLARIS_CF_NSV_ACCOUNT+"/workers/scripts/"+encodeURIComponent(worker.name)+"/content/v2";
     const r=await fetch(url,{headers:{authorization:"Bearer "+env.POLARIS_CF_NSV_READ_TOKEN,accept:"application/javascript"}});
     if(!r.ok)parts.push("Cloudflare Worker "+worker.name+" source returned HTTP "+r.status+".");
     else{
      const raw=await r.text();
      const body=polarisRedactSource(raw).slice(0,5500);
      parts.push("[LIVE CLOUDFLARE WORKER SOURCE (read-only): "+worker.name+"]\n"+body);
     }
    }catch(e){parts.push("Cloudflare Worker source could not be loaded right now.")}
   }
  }
 }
 return parts.slice(0,4).join("\n\n").slice(0,11800);
}

// POLARIS RELATIONAL ROUTER v2.4
// A single AI conversation is preserved. This module supplies source-specific facts
// from read-only tools ONLY when needed, without granting the model arbitrary SQL.
const POLARIS_ROUTED_TOOLS=["conversation","project-history","project-directory","project-source","live-metrics"];
function polarisRouteIntent(question, project){
 const q=String(question||"").toLowerCase();
 if((/\b(?:how many|number of|count|total)\b/.test(q)&&/\b(?:organizations?|organisations?|orgs?|registered accounts?)\b/.test(q))&&(project==="LiveBridge"||/\blive\s?bridge\b/.test(q)))return "live-metrics";
 if(/\b(?:website|site|url|domain|link|web address)\b/.test(q)&&/\b(?:give|what|where|send|open|share|visit|link|website|site)\b/.test(q))return "project-directory";
 if(/\b(?:last|previous|earlier|yesterday|recent|remember|recall|what did we|we did|we changed|completed|finished|outstanding|remaining|four things|four items|to.do|tasks?|milestones?)\b/.test(q))return "project-history";
 if(/\b(?:github|cloudflare|workers?|scripts?|repository|repos?|source code|files?|inspect|codebase|deploy|deployment)\b/.test(q))return "project-source";
 return "conversation";
}
function polarisResolveProject(question,selected,prior){
 const explicit=polarisProjectName(question);
 if(explicit)return {name:explicit,origin:"question"};
 if(typeof selected==="string"&&POLARIS_KNOWN_PROJECTS.includes(selected)&&selected!=="Other / Client Projects")return {name:selected,origin:"project-picker"};
 // Unnamed follow-ups inherit the most recent named project rather than starting fresh.
 const follow=/\b(?:it|its|that|those|this|the site|the website|last|previous|before|we did|we changed|give me the link|what about|how about|them|there)\b/i.test(question);
 if(follow){
  for(const r of (prior||[]).slice().reverse()){
   if(r.project&&POLARIS_KNOWN_PROJECTS.includes(r.project))return {name:r.project,origin:"conversation"};
   const inferred=polarisProjectName(r.user_text||"");
   if(inferred)return {name:inferred,origin:"conversation"};
  }
 }
 return {name:"",origin:"none"};
}
function polarisRelevance(question,memory){
 const q=String(question||"").toLowerCase();
 const hay=String(memory.title+" "+memory.details).toLowerCase();
 let score=0;
 for(const word of [...new Set(q.split(/[^a-z0-9]+/).filter(x=>x.length>=4&&!["what","where","when","were","that","this","with","about","please","tell","would","have","could","your","their","from","last"].includes(x)))]){
  if(hay.includes(word))score+=3;
  if(String(memory.title).toLowerCase().includes(word))score+=4;
 }
 return score;
}
async function polarisRetrieveMemory(env,project,route,question){
 if(!project||!env.POLARIS_DB)return "";
 try{
  const q=await env.POLARIS_DB.prepare("SELECT category,title,details,source,as_of,verified_live FROM project_memory WHERE project=? LIMIT 35").bind(project).all();
  const records=q.results||[];
  const priority={ "project-directory":["website","overview"],"project-history":["history"],"live-metrics":["overview"],"project-source":["overview"],"conversation":["overview","history"]};
  const kind=priority[route]||["overview"];
  records.sort((a,b)=>{
   const p=(x)=>kind.includes(x.category)?30:0;
   return p(b)+polarisRelevance(question,b)-(p(a)+polarisRelevance(question,a));
  });
  const take=route==="project-history"?4:route==="project-directory"?3:route==="conversation"?2:2;
  const entries=records.slice(0,take).filter(x=>route!=="project-directory"||x.category==="website"||x.category==="overview");
  if(!entries.length)return "";
  return entries.map(x=>"[PROJECT MEMORY "+x.category.toUpperCase()+" · "+x.title+" · as of "+x.as_of+"; source: "+x.source+"; "+(x.verified_live?"source verified":"historical report, not live-verified")+"]\n"+x.details).join("\n\n").slice(0,9200);
 }catch(e){return "Stored project memory was temporarily unavailable."}
}
async function polarisReadLiveStats(env,project,route){
 if(route!=="live-metrics"||project!=="LiveBridge")return "";
 if(!env.LIVEBRIDGE_METRICS_DB)return "LiveBridge production database is not connected in Polaris. Do not guess counts.";
 try{
  // Fixed read-only aggregate. No organization names, IDs or personal data are fetched.
  const v=await env.LIVEBRIDGE_METRICS_DB.prepare("SELECT COUNT(*) AS total, COALESCE(SUM(CASE WHEN account_status='active' THEN 1 ELSE 0 END),0) AS active FROM organizations").first();
  if(!v||!Number.isFinite(Number(v.total)))return "LiveBridge organization count query returned no valid result.";
  return "[LIVE READ-ONLY METRICS · source: livebridge Worker TRANSLATIONS_DB · fetched "+new Date().toISOString()+"]\nRegistered organization records: "+Number(v.total)+". Active organization records: "+Number(v.active)+". These are organization rows, not necessarily ministry parent accounts or campus count. Do not extrapolate beyond this database.";
 }catch(e){return "Unable to read the live LiveBridge organization count. Do not invent a number."}
}
async function polarisBuildEvidence(env,question,selected,prior){
 const resolved=polarisResolveProject(question,selected,prior);
 const project=resolved.name;
 const route=polarisRouteIntent(question,project);
 const memory=await polarisRetrieveMemory(env,project,route,question);
 let directory="",live="",source="";
 if(route==="project-directory"&&project==="TapBin")directory="[VERIFIED PROJECT DIRECTORY] TapBin official site: https://tapbin.ca .";
 if(route==="project-directory"&&project==="Songwriters Compass")directory="[PROJECT DIRECTORY, previously reported] https://compass.northstarventures.ca . The site's current availability was not independently verified here.";
 if(route==="live-metrics")live=await polarisReadLiveStats(env,project,route);
 return {project,route,origin:resolved.origin,memory,directory,live};
}

// POLARIS ChatGPT export bridge v2.4.
// The OpenAI API does NOT provide ChatGPT account history. User-approved export
// files are imported via authenticated endpoints into this private D1 journal.
// Never automatically import files from GitHub, Gmail, or other connected apps.
const POLARIS_IMPORT_PROJECTS=["Polaris","North Star Ventures","HOH HUB","LiveBridge","TapBin","Songwriters Compass","X32 AI Engineer","Great Church","Healing The Heart","Northstar Organizer","Other / Client Projects"];
function polarisImportClean(value,max){
 return String(value||"").slice(0,max).replace(/\b(?:sk-[A-Za-z0-9_-]{16,}|github_pat_[A-Za-z0-9_]{20,}|gh[pousr]_[A-Za-z0-9_]{20,})\b/g,"[REDACTED KEY]")
  .replace(/(\b(?:password|secret|api[_ -]?key|access[_ -]?code|access[_ -]?token)\b\s*(?:is|:|=)\s*)[^\s,;]{6,}/gi,"$1[REDACTED]");
}
async function polarisImportHistory(request,env){
 if(!env.POLARIS_DB)return json({error:"Private knowledge database unavailable"},503);
 let raw;try{raw=await request.text()}catch(e){return json({error:"Could not read import data"},400)}
 if(raw.length>130000)return json({error:"Import batch is too large. Reduce the batch size."},413);
 let data;try{data=JSON.parse(raw)}catch(e){return json({error:"Invalid import JSON"},400)}
 if(!Array.isArray(data?.messages)||data.messages.length<1||data.messages.length>25)return json({error:"Import 1–25 text messages per batch"},400);
 const sql="INSERT OR REPLACE INTO imported_chat_messages(id,conversation_id,project,title,role,content,message_time) VALUES(?,?,?,?,?,?,?)";
 const staged=[],ids=[];
 for(const m of data.messages){
  if(!m||typeof m!=="object")continue;
  const project=POLARIS_IMPORT_PROJECTS.includes(m.project)?m.project:"Other / Client Projects";
  const conversationId=String(m.conversation_id||"").slice(0,100);
  const id=String(m.id||"").slice(0,150);
  const role=m.role==="assistant"?"assistant":m.role==="user"?"user":"";
  const title=polarisImportClean(m.title,200),content=polarisImportClean(m.content,4600);
  const sentAt=String(m.message_time||"").slice(0,35);
  if(!/^[a-zA-Z0-9_-]{12,150}$/.test(id)||!role||!content.trim()||!conversationId)continue;
  staged.push({id,conversationId,project,title,role,content,sentAt});
  ids.push(id);
 }
 if(!staged.length)return json({error:"No valid text messages found in batch"},400);
 try{
  const writes=staged.map(m=>env.POLARIS_DB.prepare(sql).bind(m.id,m.conversationId,m.project,m.title,m.role,m.content,m.sentAt));
  await env.POLARIS_DB.batch(writes);
  const ftsSql="INSERT OR REPLACE INTO imported_chat_fts(rowid,content,title,project,message_id) VALUES((SELECT rowid FROM imported_chat_messages WHERE id=?),?,?,?,?)";
  await env.POLARIS_DB.batch(staged.map(m=>env.POLARIS_DB.prepare(ftsSql).bind(m.id,m.content,m.title,m.project,m.id)));
  return json({ok:true,imported:staged.length});
 }catch(e){return json({error:"Could not store imported messages"},502)}
}
async function polarisImportStatus(env){
 if(!env.POLARIS_DB)return json({error:"Private knowledge database unavailable"},503);
 try{
  const r=await env.POLARIS_DB.prepare("SELECT project,COUNT(*) AS messages,COUNT(DISTINCT conversation_id) AS conversations FROM imported_chat_messages GROUP BY project ORDER BY messages DESC").all();
  return json({projects:r.results||[],method:"user-approved ChatGPT conversations.json",automatic_sync:false});
 }catch(e){return json({error:"Could not read imported-history status"},502)}
}
async function polarisImportClear(request,env){
 if(!env.POLARIS_DB)return json({error:"Private knowledge database unavailable"},503);
 let data;try{data=await request.json()}catch(e){return json({error:"Invalid request"},400)}
 if(data?.confirm!=="DELETE IMPORTED CHATGPT HISTORY")return json({error:"Explicit confirmation required"},400);
 try{
  await env.POLARIS_DB.prepare("DELETE FROM imported_chat_messages").run();
  await env.POLARIS_DB.prepare("DELETE FROM imported_chat_fts").run();
  return json({ok:true,deleted:true});
 }catch(e){return json({error:"Could not clear imported ChatGPT history"},502)}
}
async function polarisSearchImportedChats(env,project,question){
 if(!env.POLARIS_DB||!project)return "";
 const tokens=[...new Set(String(question||"").toLowerCase().split(/[^a-z0-9]+/).filter(t=>t.length>=3&&!["how","what","the","our","you","can","were","did","for","from","with","about","please","tell","those","this","that","your","these","last","earlier"].includes(t)))].slice(0,8);
 if(!tokens.length)return "";
 try{
  const search=tokens.map(t=>'"'+t+'"*').join(" OR ");
  const rows=await env.POLARIS_DB.prepare("SELECT m.project,m.title,m.role,m.content,m.message_time,m.conversation_id FROM imported_chat_fts f JOIN imported_chat_messages m ON m.rowid=f.rowid WHERE imported_chat_fts MATCH ? AND m.project=? ORDER BY bm25(imported_chat_fts) ASC LIMIT 8").bind(search,project).all();
  const hits=rows.results||[];
  if(!hits.length)return "";
  return "[USER-IMPORTED CHATGPT HISTORY — this is a point-in-time copy, not live ChatGPT access]\n"+
   hits.map(r=>"Chat title: "+r.title+" · "+(r.message_time||"undated")+" · "+r.role+"\n"+String(r.content).slice(0,1800)).join("\n\n").slice(0,9200);
 }catch(e){return ""}
}

const POLARIS_CLIENT_DIAGNOSTICS = "/* Polaris v2.7 browser diagnostics. No screenshots, text input, passwords or stack traces are sent. */\n(function(){\n var sent=0,seen={};\n function report(message,severity){\n  if(sent>=4)return;\n  var clean=String(message||\"Unknown browser exception\").replace(/[\\u0000-\\u001f\\u007f]/g,\" \").slice(0,170);\n  clean=clean.replace(/\\b(?:sk-[A-Za-z0-9_-]{12,}|ghp_[A-Za-z0-9_-]{16,})\\b/gi,\"[REDACTED]\");\n  if(seen[clean])return;seen[clean]=true;sent++;\n  fetch(\"/api/diagnostic\",{method:\"POST\",credentials:\"same-origin\",keepalive:true,headers:{\"content-type\":\"application/json\"},body:JSON.stringify({project_key:\"polaris\",severity:severity||\"error\",summary:clean})}).catch(function(){});\n }\n window.addEventListener(\"error\",function(event){\n  if(event.target&&event.target!==window)return;\n  report(event.message||\"Unspecified JavaScript error\",\"error\");\n });\n window.addEventListener(\"unhandledrejection\",function(event){\n  var reason=event.reason;\n  report(\"Unhandled promise: \"+(reason&&reason.name?reason.name+\": \":\"\")+(reason&&reason.message?reason.message:\"No details\"),\"warning\");\n });\n})();\n";
const POLARIS_COMMAND_HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex,nofollow\"><meta name=\"theme-color\" content=\"#061021\"><title>POLARIS · OPERATIONS</title><style>\n:root{color-scheme:dark;--bg:#030912;--panel:#0a1e34e8;--line:#4f9cce44;--accent:#67e5ff;--ink:#eaf7ff;--muted:#8aacc5;--green:#68f6c3;--amber:#ffce77;--red:#ff898c}\n*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 0,#122f57 0,transparent 45%),radial-gradient(ellipse at 92% 85%,#19103a 0,transparent 42%),var(--bg);color:var(--ink);font:14px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif}\nbody:before{content:\"\";position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(#69aae509 1px,transparent 1px),linear-gradient(90deg,#69aae509 1px,transparent 1px);background-size:38px 38px}\nbutton,a{font:inherit}a{color:var(--accent)}main{max-width:1440px;margin:0 auto;padding:clamp(15px,3vw,32px);position:relative}\nheader{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;border-bottom:1px solid var(--line);padding-bottom:16px}.brand{display:flex;align-items:center;gap:12px}\n.logo{height:46px;width:46px;display:grid;place-items:center;border:1px solid #51cdf59c;border-radius:13px;color:#a3efff;font-size:31px;box-shadow:0 0 24px #31b5ec30;background:#0b2845}\n.name{font-size:21px;letter-spacing:.19em;font-weight:900;line-height:1.05}.eyebrow{color:#84bdd9;font-size:10px;letter-spacing:.15em;font-weight:750;margin-top:7px}\n.nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.nav a{text-decoration:none;border:1px solid #427ea67a;border-radius:9px;padding:8px 12px;background:#09213c;color:#c4e7fd;font-size:12px;font-weight:700}.status{border:1px solid #3bc5ac7b;border-radius:25px;background:#0a2d30;padding:7px 10px;color:#9ef8df;font-size:10px;font-weight:800;letter-spacing:.11em}\nh1{font-size:clamp(27px,4.8vw,55px);letter-spacing:-.045em;margin:22px 0 8px;line-height:1.15}.lead{color:var(--muted);font-size:13px;max-width:900px;margin:0 0 20px}.tag{font-size:10px;color:var(--accent);letter-spacing:.16em;font-weight:800}\n.miniGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin-bottom:18px}.mini{background:linear-gradient(145deg,#143451bd,#09192ccf);border:1px solid var(--line);border-radius:14px;padding:16px}.mini strong{display:block;font-size:clamp(23px,3vw,37px);letter-spacing:-.05em;line-height:1.1;margin:8px 0 5px}.mini span{color:#95bfd7;font-size:10px;letter-spacing:.07em;font-weight:800}.mini small{color:#7fa2b9;font-size:11px}\n.grid{display:grid;grid-template-columns:1.12fr 1fr;gap:14px}.pane{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:clamp(15px,2.2vw,23px);margin-bottom:14px;min-width:0}.panelhead{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:15px;padding-bottom:12px;border-bottom:1px solid #417fa644}.panelhead h2{font-size:13px;letter-spacing:.11em;color:#a1e9ff;margin:0;font-weight:850}.hint{font-size:10px;color:#90b7c9}\n.project{padding:13px 0;border-bottom:1px solid #407da935}.project:last-child{border-bottom:0}.prhead{display:flex;align-items:center;justify-content:space-between;gap:7px}.prname{font-size:14px;font-weight:800}.pill{font-size:9px;border-radius:30px;padding:5px 8px;border:1px solid #4e9da67b;color:#90e8d3;background:#0f3044;white-space:nowrap;font-weight:800;letter-spacing:.03em}.pill.warn{color:var(--amber);border-color:#b58e4f88}.pill.bad{color:var(--red);border-color:#cb596587}.project p{font-size:12px;line-height:1.5;color:#a1bcce;margin:6px 0}.project .next{color:#bde7e9;font-size:12px;margin-top:9px}.project .next b{color:var(--accent)}.project a{text-decoration:none;font-weight:700;font-size:11px}\n.kpis{display:flex;gap:7px;flex-wrap:wrap;margin:8px 0}.kpis span{border:1px solid #37688977;border-radius:7px;background:#08192d;padding:4px 7px;font-size:10px;color:#b2d2e6}\n.task{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid #407da935;align-items:flex-start}.task:last-child{border:0}.number{flex:none;color:#92e7ff;border-radius:8px;background:#0b3350;border:1px solid #56b2db50;padding:5px 7px;min-width:32px;text-align:center;font-size:11px;font-weight:800}.tasktitle{font-weight:750;font-size:12px}.taskdetail{color:#8eacc1;font-size:11px;margin:4px 0}.taskfoot{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:10px;color:#76a7c4}.dot{height:7px;width:7px;border-radius:50%;background:#69e4a9;box-shadow:0 0 11px #49dda578}.dot.bad{background:#fa8795;box-shadow:0 0 11px #fc718c78}.dot.warn{background:#eac379}.healthline{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #407da935}.healthline:last-child{border:0}.statusname{display:flex;gap:9px;align-items:center;font-size:12px;font-weight:700}.sublabel{font-size:10px;color:#85abc6}.briefing{white-space:normal;line-height:1.6;font-size:12px;color:#afd1e3}.briefing strong{font-size:15px;color:#b5f1ff}.briefing .point{padding:8px 0;border-bottom:1px solid #407da935}.briefing .point:last-child{border-bottom:0}.footer{font-size:10px;color:#688ea7;border-top:1px solid var(--line);padding-top:13px;margin-top:12px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}\n.error{color:#ffc7c7;border:1px solid #c96d7b79;border-radius:10px;padding:12px;display:none;margin:10px 0}.empty{color:#789eb6;font-size:12px}.stamp{color:#7091a8;font-size:10px;white-space:nowrap}\n@media(max-width:900px){.grid{grid-template-columns:1fr}.miniGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:490px){.mini{padding:12px}.name{font-size:17px}.logo{height:40px;width:40px}main{padding:14px}.pill{font-size:9px}h1{font-size:30px}}\n</style></head><body><main>\n<header><div class=\"brand\"><div class=\"logo\">✦</div><div><div class=\"name\">POLARIS</div><div class=\"eyebrow\">NORTH STAR VENTURES · OPERATIONS</div></div></div><div class=\"nav\"><span id=\"connection\" class=\"status\">CONNECTING</span><a href=\"/display\">LIVE DISPLAY</a><a href=\"/\">DASHBOARD</a></div></header>\n<div class=\"tag\" style=\"margin-top:21px\">◉ PROJECT INTELLIGENCE · REUSABLE COMMAND CENTRE</div><h1>NorthStar Operations</h1><p class=\"lead\">Persistent project knowledge, verified monitoring, task progress, diagnostics and your morning briefing—all in one display. ChatGPT remains your interactive assistant.</p>\n<div id=\"error\" class=\"error\"></div>\n<div class=\"miniGrid\"><div class=\"mini\"><span>TRACKED PROJECTS</span><strong id=\"numProjects\">—</strong><small>Permanent project records</small></div><div class=\"mini\"><span>OUTSTANDING TASKS</span><strong id=\"numTasks\">—</strong><small>Across all workstreams</small></div><div class=\"mini\"><span>RESPONDING SITES</span><strong id=\"numResponding\">—</strong><small>Based on latest checks</small></div><div class=\"mini\"><span>OPEN DIAGNOSTICS</span><strong id=\"numErrors\">—</strong><small>Captured errors and alerts</small></div></div>\n<div class=\"grid\"><section>\n<div class=\"pane\"><div class=\"panelhead\"><h2>◈ PROJECT INTELLIGENCE</h2><span class=\"hint\">SAVED IN CLOUDFLARE D1</span></div><div id=\"projects\" class=\"empty\">Loading projects…</div></div>\n<div class=\"pane\"><div class=\"panelhead\"><h2>☷ DEVELOPMENT QUEUE</h2><span class=\"hint\">PRIORITY ORDER</span></div><div id=\"tasks\" class=\"empty\">Loading work items…</div></div>\n</section><section>\n<div class=\"pane\"><div class=\"panelhead\"><h2>◉ AUTOMATIC MONITORING</h2><span id=\"monitorTime\" class=\"hint\">CHECKS PENDING</span></div><div id=\"health\" class=\"empty\">Waiting for scheduled monitor data…</div><p class=\"hint\" style=\"margin-bottom:0\">HTTP status is a connectivity check—not a test of sign-in, checkout, or live streaming. Numbers are timestamped snapshots.</p></div>\n<div class=\"pane\"><div class=\"panelhead\"><h2>☀ MORNING BRIEFING</h2><span id=\"briefDate\" class=\"hint\">7 AM ALBERTA</span></div><div id=\"briefing\" class=\"briefing\">Preparing the first scheduled briefing.</div></div>\n<div class=\"pane\"><div class=\"panelhead\"><h2>⚠ ERROR DIAGNOSTICS</h2><span class=\"hint\">OPEN ISSUES ONLY</span></div><div id=\"errors\" class=\"empty\">No error events captured.</div><p class=\"hint\">Polaris and website availability events are connected. Deep application error capture for other products requires separate consent-based instrumentation.</p></div>\n</section></div><div class=\"footer\"><span>CHATGPT IS YOUR ASSISTANT · POLARIS IS YOUR DISPLAY</span><span id=\"lastUpdated\">WAITING FOR FIRST DATA</span></div>\n</main><script>\n(function(){\n\"use strict\";\nconst byId=id=>document.getElementById(id);\nconst set=(id,s)=>{byId(id).textContent=String(s==null?\"\":s)};\nconst el=(tag,cls,txt)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(txt!=null)x.textContent=String(txt);return x};\nconst when=d=>{if(!d)return\"Not yet checked\";try{return new Date(d).toLocaleString([],{month:\"short\",day:\"numeric\",hour:\"numeric\",minute:\"2-digit\"})}catch(e){return String(d)}};\nconst statusName=x=>x===\"responding\"?\"Responding\":x===\"unreachable\"?\"Unreachable\":x===\"degraded\"?\"Restricted/degraded\":\"Not checked\";\nconst label=(text,kind)=>{const x=el(\"span\",\"pill\"+(kind?\" \"+kind:\"\"),text);return x};\nfunction metrics(x){return x&&typeof x===\"object\"&&!Array.isArray(x)?Object.entries(x).filter(([k])=>k!==\"error\").slice(0,4):[]}\nfunction render(data){\n const projects=data.projects||[],tasks=data.tasks||[],health=data.health||[],errors=data.errors||[];\n const statuses=new Map(health.map(x=>[x.project_key,x]));\n set(\"numProjects\",projects.length);set(\"numTasks\",tasks.filter(x=>x.status!==\"done\").length);set(\"numResponding\",health.filter(x=>x.state===\"responding\").length+\"/\"+(health.length||\"—\"));set(\"numErrors\",errors.length);\n set(\"connection\",\"● CONNECTED\");\n const projectBox=byId(\"projects\");projectBox.replaceChildren();\n projects.forEach(p=>{\n  const item=el(\"article\",\"project\");const top=el(\"div\",\"prhead\"),title=el(\"div\",\"prname\",p.project_name),h=statuses.get(p.project_key);\n  top.append(title,label(h?statusName(h.state):\"Tracked\",h?.state===\"unreachable\"?\"bad\":h?.state===\"degraded\"?\"warn\":\"\"));item.append(top);\n  item.append(el(\"p\",\"\",p.context_summary||\"Project details being indexed\"));\n  const verified=el(\"p\",\"\",p.verified_summary||\"No verified details yet\");verified.style.color=\"#7de8c5\";item.append(verified);\n  if(h&&metrics(h.metrics).length){const kpis=el(\"div\",\"kpis\");metrics(h.metrics).forEach(([k,v])=>kpis.append(el(\"span\",\"\",k.replace(/_/g,\" \")+\": \"+v)));item.append(kpis)}\n  if(p.next_step){const next=el(\"p\",\"next\");next.append(el(\"b\",\"\",\"Next: \"));next.append(document.createTextNode(p.next_step));item.append(next)}\n  if(p.site_url){try{const url=new URL(p.site_url);if(url.protocol===\"https:\"){const a=el(\"a\",\"\",\"OPEN SITE ↗\");a.href=url.href;a.target=\"_blank\";a.rel=\"noopener noreferrer\";item.append(a)}}catch(e){}}\n  projectBox.append(item);\n });\n const tbox=byId(\"tasks\");tbox.replaceChildren();\n tasks.filter(x=>x.status!==\"done\").slice(0,16).forEach((t,i)=>{\n  const item=el(\"div\",\"task\");item.append(el(\"div\",\"number\",String(i+1).padStart(2,\"0\")));\n  const body=el(\"div\");body.append(el(\"div\",\"tasktitle\",t.title));\n  body.append(el(\"div\",\"taskdetail\",t.details));const foot=el(\"div\",\"taskfoot\");foot.append(label(t.project_key));foot.append(label(t.status));foot.append(el(\"span\",\"\",\"Priority \"+t.priority));body.append(foot);item.append(body);tbox.append(item);\n });if(!tbox.children.length)tbox.append(el(\"p\",\"empty\",\"No outstanding tasks.\"));\n const hb=byId(\"health\");hb.replaceChildren();\n health.forEach(h=>{const row=el(\"div\",\"healthline\"),left=el(\"div\"),nm=el(\"div\",\"statusname\");nm.append(el(\"span\",\"dot\"+(h.state===\"unreachable\"?\" bad\":h.state===\"degraded\"?\" warn\":\"\")));nm.append(el(\"span\",\"\",h.project_key));left.append(nm);left.append(el(\"div\",\"sublabel\",statusName(h.state)+(h.http_status?\" · HTTP \"+h.http_status:\"\")+\" · \"+when(h.sampled_at)));row.append(left,el(\"div\",\"stamp\",h.latency_ms==null?\"\":h.latency_ms+\" ms\"));hb.append(row)});\n if(!health.length)hb.append(el(\"p\",\"empty\",\"First monitoring cycle pending.\"));\n set(\"monitorTime\",data.monitor?.completed_at?\"LAST CHECK \"+when(data.monitor.completed_at):\"FIRST CHECK PENDING\");\n const brief=byId(\"briefing\");brief.replaceChildren();\n if(data.briefing){const b=data.briefing;brief.append(el(\"strong\",\"\",b.headline||\"Morning summary\"));(b.priorities||[]).slice(0,5).forEach(x=>brief.append(el(\"div\",\"point\",\"• \"+x.project_key+\": \"+x.title)));set(\"briefDate\",b.date+\" · 7 AM\")}else{brief.append(el(\"p\",\"empty\",\"The first automated 7 AM Alberta briefing has not run yet.\"));set(\"briefDate\",\"7 AM ALBERTA\")}\n const eb=byId(\"errors\");eb.replaceChildren();\n if(!errors.length)eb.append(el(\"p\",\"empty\",\"No diagnostic events recorded yet.\"));\n errors.slice(0,8).forEach(e=>{const line=el(\"div\",\"task\");const marker=el(\"span\",\"dot\"+(e.severity===\"warning\"?\" warn\":\" bad\"));const b=el(\"div\");b.append(el(\"div\",\"tasktitle\",e.project_key+\" · \"+e.summary));b.append(el(\"div\",\"sublabel\",when(e.last_seen)+\" · \"+e.occurrences+\" occurrence(s)\"));line.append(marker,b);eb.append(line)});\n set(\"lastUpdated\",\"RENDERED \"+when(data.updated));\n}\nasync function refresh(){\n try{const response=await fetch(\"/api/command-centre\",{credentials:\"same-origin\",cache:\"no-store\"});if(!response.ok)throw Error(\"Data unavailable\");render(await response.json());byId(\"error\").style.display=\"none\"}\n catch(e){set(\"connection\",\"OFFLINE\");const err=byId(\"error\");err.style.display=\"block\";err.textContent=\"Unable to load Polaris operations. Verify you are signed in.\"}\n}\nrefresh();setInterval(()=>{if(!document.hidden)refresh()},30000);\ndocument.addEventListener(\"visibilitychange\",()=>{if(!document.hidden)refresh()});\n})();\n</script><script>\n/* Polaris v2.7 browser diagnostics. No screenshots, text input, passwords or stack traces are sent. */\n(function(){\n var sent=0,seen={};\n function report(message,severity){\n  if(sent>=4)return;\n  var clean=String(message||\"Unknown browser exception\").replace(/[\\u0000-\\u001f\\u007f]/g,\" \").slice(0,170);\n  clean=clean.replace(/\\b(?:sk-[A-Za-z0-9_-]{12,}|ghp_[A-Za-z0-9_-]{16,})\\b/gi,\"[REDACTED]\");\n  if(seen[clean])return;seen[clean]=true;sent++;\n  fetch(\"/api/diagnostic\",{method:\"POST\",credentials:\"same-origin\",keepalive:true,headers:{\"content-type\":\"application/json\"},body:JSON.stringify({project_key:\"polaris\",severity:severity||\"error\",summary:clean})}).catch(function(){});\n }\n window.addEventListener(\"error\",function(event){\n  if(event.target&&event.target!==window)return;\n  report(event.message||\"Unspecified JavaScript error\",\"error\");\n });\n window.addEventListener(\"unhandledrejection\",function(event){\n  var reason=event.reason;\n  report(\"Unhandled promise: \"+(reason&&reason.name?reason.name+\": \":\"\")+(reason&&reason.message?reason.message:\"No details\"),\"warning\");\n });\n})();\n\n</script></body></html>";
/* Polaris command centre operations - included into worker.js on deploy. */
const CMDSITES=[{key:"tapbin",url:"https://tapbin.ca"},{key:"livebridge",url:"https://livebridge.ca"},{key:"compass",url:"https://compass.northstarventures.ca"},{key:"greatchurch",url:"https://greatchurch.ca"}];
function cmdJSON(data,status=200){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}})}
function cmdClean(x,max){return String(x==null?"":x).replace(/[\u0000-\u001f\u007f]/g," ").slice(0,max).replace(/\b(?:sk-[A-Za-z0-9_-]{12,}|ghp_[A-Za-z0-9_-]{16,})\b/gi,"[REDACTED]").replace(/\b(password|secret|token|api.key)\s*(?:is|:|=)\s*\S+/gi,"[REDACTED]").trim()}
async function cmdSummary(env){
 const db=env.POLARIS_DB;
 const [a,b,c,d,e,f]=await Promise.all([
  db.prepare("SELECT project_key,project_name,site_url,context_summary,verified_summary,verified_at,next_step,source_ref,status FROM polaris_project_intelligence ORDER BY CASE project_key WHEN 'polaris' THEN 0 ELSE 1 END,project_name").all(),
  db.prepare("SELECT id,project_key,title,details,priority,status,requires_approval,updated_at FROM polaris_work_queue ORDER BY CASE status WHEN 'in_progress' THEN 0 WHEN 'blocked' THEN 1 WHEN 'verification' THEN 2 ELSE 3 END,priority,updated_at DESC LIMIT 60").all(),
  db.prepare("SELECT project_key,sampled_at,state,http_status,latency_ms,metric_json,details FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY project_key ORDER BY sampled_at DESC,id DESC) AS rnk FROM polaris_health_samples) WHERE rnk=1 ORDER BY project_key").all(),
  db.prepare("SELECT id,project_key,severity,summary,source,occurrences,last_seen FROM polaris_error_events WHERE resolved=0 ORDER BY last_seen DESC LIMIT 15").all(),
  db.prepare("SELECT local_date,created_at,briefing_json FROM polaris_briefings ORDER BY local_date DESC LIMIT 1").all(),
  db.prepare("SELECT started_at,completed_at,state,notes FROM polaris_monitor_runs ORDER BY started_at DESC LIMIT 1").all()
 ]);
 const health=(c.results||[]).map(function(x){let metrics={};try{metrics=JSON.parse(x.metric_json||"{}")}catch(e){}return {...x,metrics}});
 const briefing=(e.results||[])[0];let brief=null;try{if(briefing)brief={date:briefing.local_date,createdAt:briefing.created_at,...JSON.parse(briefing.briefing_json)}}catch(e){}
 return {projects:a.results||[],tasks:b.results||[],health,errors:d.results||[],briefing:brief,monitor:(f.results||[])[0]||null,updated:new Date().toISOString(),note:"Health checks, not complete user-journey tests; statistics reflect sampled D1 values."};
}
function cmdOrigin(request,url){return request.headers.get("origin")===url.origin}
async function cmdTaskCreate(request,env,url){
 if(!cmdOrigin(request,url))return cmdJSON({error:"Same-origin required"},403);
 let d;try{const s=await request.text();if(s.length>2700)return cmdJSON({error:"Too much content"},413);d=JSON.parse(s)}catch(e){return cmdJSON({error:"Invalid request"},400)}
 const title=cmdClean(d.title,140),details=cmdClean(d.details,950),project=cmdClean(d.project_key,40),priority=Math.min(5,Math.max(1,Number(d.priority)||3));
 if(title.length<3||!/^[a-z0-9-]{2,35}$/.test(project))return cmdJSON({error:"Title and project required"},400);
 const found=await env.POLARIS_DB.prepare("SELECT project_key FROM polaris_project_intelligence WHERE project_key=?").bind(project).first();
 if(!found)return cmdJSON({error:"Unknown project"},400);
 const id=crypto.randomUUID();
 await env.POLARIS_DB.prepare("INSERT INTO polaris_work_queue(id,project_key,title,details,priority,status,requires_approval,source) VALUES(?,?,?,?,?,'backlog',1,'manual')").bind(id,project,title,details,priority).run();
 return cmdJSON({ok:true,id,status:"backlog"});
}
async function cmdTaskUpdate(request,env,url){
 if(!cmdOrigin(request,url))return cmdJSON({error:"Same-origin required"},403);
 let d;try{const s=await request.text();if(s.length>900)return cmdJSON({error:"Too much content"},413);d=JSON.parse(s)}catch(e){return cmdJSON({error:"Invalid request"},400)}
 if(!/^(?:[a-z0-9-]{4,64})$/.test(String(d.id||""))||!["backlog","ready","in_progress","blocked","verification","done"].includes(d.status))return cmdJSON({error:"Invalid task or status"},400);
 const r=await env.POLARIS_DB.prepare("UPDATE polaris_work_queue SET status=?,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=?").bind(d.status,d.id).run();
 return cmdJSON({ok:Boolean(r.meta?.changes),changed:r.meta?.changes||0});
}
async function cmdHash(s){const h=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return Array.from(new Uint8Array(h)).slice(0,12).map(x=>x.toString(16).padStart(2,"0")).join("")}
async function cmdLogError(env,project,summary,source,severity){
 if(!env.POLARIS_DB)return;
 const safe=cmdClean(summary,210),id=await cmdHash(project+"|"+source+"|"+safe),now=new Date().toISOString();
 try{await env.POLARIS_DB.prepare("INSERT INTO polaris_error_events(id,project_key,severity,summary,fingerprint,source,first_seen,last_seen) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET occurrences=occurrences+1,last_seen=excluded.last_seen,resolved=0").bind(id,project,severity||"error",safe,id,source,now,now).run()}catch(e){}
}
async function cmdClientError(request,env,url){
 if(!cmdOrigin(request,url))return cmdJSON({error:"Same-origin required"},403);
 let d;try{const s=await request.text();if(s.length>1500)return cmdJSON({error:"Too much content"},413);d=JSON.parse(s)}catch(e){return cmdJSON({error:"Invalid input"},400)}
 if(d.project_key!=="polaris"||!["warning","error"].includes(d.severity))return cmdJSON({error:"Only Polaris errors accepted"},400);
 await cmdLogError(env,"polaris",d.summary||"Client error","polaris-dashboard",d.severity);return cmdJSON({ok:true});
}
async function cmdMetrics(kind,db){
 if(!db)return {};
 try{
  if(kind==="tapbin"){const [a,b]=await Promise.all([db.prepare("SELECT COUNT(*) AS n FROM saas_users WHERE role='organization'").first(),db.prepare("SELECT COALESCE(SUM(requests),0) AS n FROM saas_ai_usage").first()]);return {accounts:a.n,ai_requests:b.n}}
  if(kind==="livebridge"){const [a,b,r]=await Promise.all([db.prepare("SELECT COUNT(*) AS n FROM organizations").first(),db.prepare("SELECT COUNT(*) AS n FROM broadcast_sessions").first(),db.prepare("SELECT COUNT(*) AS n FROM active_broadcasts WHERE last_seen>=(strftime('%s','now')*1000)-120000").first()]);return {organizations:a.n,broadcasts:b.n,recent_rooms:r.n}}
  if(kind==="compass"){const [a,b,z]=await Promise.all([db.prepare("SELECT COUNT(*) AS n FROM users").first(),db.prepare("SELECT COUNT(*) AS n FROM songs").first(),db.prepare("SELECT COUNT(*) AS n FROM ai_call_logs").first()]);return {users:a.n,songs:b.n,ai_calls:z.n}}
 }catch(e){return {error:"Metrics unavailable"}}
 return {};
}
async function cmdCheck(site,env,now){
 const started=Date.now();let state="unknown",status=null,details="",elapsed=0;
 try{
  const r=await fetch(site.url,{method:"GET",redirect:"manual",signal:AbortSignal.timeout(9500)});
  status=r.status;state=status>=200&&status<400?"responding":status<500?"degraded":"unreachable";
  details=state==="responding"?"HTTP response received":"HTTP "+status;
  try{await r.body?.cancel()}catch(e){}
 }catch(e){state="unreachable";details="HTTP request failed";}
 elapsed=Date.now()-started;
 await env.POLARIS_DB.prepare("INSERT INTO polaris_health_samples(project_key,sampled_at,state,http_status,latency_ms,source,details) VALUES(?,?,?,?,?,'scheduled-http',?)").bind(site.key,now,state,status,elapsed,details).run();
 if(state==="unreachable")await cmdLogError(env,site.key,"Website health check failed: "+(status||"network"),"scheduled-http","warning");
 return {key:site.key,state,status,elapsed};
}
async function cmdBriefing(env,date){
 const [h,t,e]=await Promise.all([
  env.POLARIS_DB.prepare("SELECT project_key,state,http_status,sampled_at FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY project_key ORDER BY sampled_at DESC,id DESC) AS rn FROM polaris_health_samples) WHERE rn=1").all(),
  env.POLARIS_DB.prepare("SELECT project_key,title,priority,status FROM polaris_work_queue WHERE status!='done' ORDER BY priority,updated_at LIMIT 10").all(),
  env.POLARIS_DB.prepare("SELECT project_key,summary,last_seen FROM polaris_error_events WHERE resolved=0 ORDER BY last_seen DESC LIMIT 8").all()
 ]);
 const sites=h.results||[],result={headline:sites.some(x=>x.state==="unreachable")?"Some systems need attention":"Project monitoring summary",sites,priorities:t.results||[],errors:e.results||[],note:"Scheduled HTTP checks and D1 snapshots; not a live audience count or functional test."};
 await env.POLARIS_DB.prepare("INSERT OR IGNORE INTO polaris_briefings(local_date,created_at,timezone,briefing_json) VALUES(?,?,'America/Edmonton',?)").bind(date,new Date().toISOString(),JSON.stringify(result)).run();
}
async function cmdScheduled(env){
 if(!env.POLARIS_DB)return;
 const now=new Date().toISOString(),id=crypto.randomUUID();
 await env.POLARIS_DB.prepare("INSERT INTO polaris_monitor_runs(id,started_at,state) VALUES(?,?,'running')").bind(id,now).run();
 try{
  const checks=await Promise.allSettled(CMDSITES.map(x=>cmdCheck(x,env,now)));
  const sources=[["tapbin",env.TAPBIN_METRICS_DB],["livebridge",env.LIVEBRIDGE_METRICS_DB],["compass",env.COMPASS_METRICS_DB]];
  for(const pair of sources){
   const m=await cmdMetrics(pair[0],pair[1]);
   await env.POLARIS_DB.prepare("UPDATE polaris_health_samples SET metric_json=? WHERE id=(SELECT id FROM polaris_health_samples WHERE project_key=? ORDER BY sampled_at DESC,id DESC LIMIT 1)").bind(JSON.stringify(m),pair[0]).run();
  }
  const parts=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{timeZone:"America/Edmonton",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",hourCycle:"h23"}).formatToParts(new Date()).filter(x=>x.type!=="literal").map(x=>[x.type,x.value]));
  if(Number(parts.hour)===7)await cmdBriefing(env,parts.year+"-"+parts.month+"-"+parts.day);
  const failed=checks.filter(x=>x.status==="rejected").length;
  await env.POLARIS_DB.prepare("UPDATE polaris_monitor_runs SET state=?,completed_at=?,notes=? WHERE id=?").bind(failed?"partial":"complete",new Date().toISOString(),String(checks.length)+" checks; "+failed+" operation failures",id).run();
  await env.POLARIS_DB.prepare("DELETE FROM polaris_health_samples WHERE sampled_at < datetime('now','-35 days')").run();
  await env.POLARIS_DB.prepare("DELETE FROM polaris_monitor_runs WHERE started_at < datetime('now','-14 days')").run();
 }catch(e){
  await cmdLogError(env,"polaris","Scheduled monitor failed ("+cmdClean(e?.name||"error",50)+")","polaris-scheduler","error");
  try{await env.POLARIS_DB.prepare("UPDATE polaris_monitor_runs SET state='error',completed_at=? WHERE id=?").bind(new Date().toISOString(),id).run()}catch(z){}
 }
}

